prts.feedbackvariables:
goodsize: is(length(ans1)=n and length(transpose(ans1))=1);
ans: if goodsize then ans1 else col(ident(n),1);
ansprod: realprod(realvect,ans);
isZero: is(ans = zeromatrix(n,1));

varlist: listofvars(ans2);
goodvarlist: is(varlist=[] or varlist=[x]);
gooddeg: is(hipow(ans2,x) <= 1);
validInput: goodvarlist and gooddeg;

ansprod: polprod(polvect,ans2);
isZero: is(ratsimp(ans2) = 0);
